data class Request(val n: Int, val reply: CompletableDeferred<Int>)

fun CoroutineScope.fibService(requests: ReceiveChannel<Request>) = launch {
    for (req in requests) req.reply.complete(fib(req.n))
}

val answer = CompletableDeferred<Int>()
requests.send(Request(10, answer))
println(answer.await())
